            val = makespan(cand)
            if val < best_val:
                best_val = val
                best_pos = pos
        seq = seq[:best_pos] + [job] + seq[best_pos:]

    # Bounded local improvement: adjacent swap search
    if n > 1:
        max_iter = max(2, min(8, 150 // max(n, 1)))
        cur_makespan = makespan(seq)
        for _ in range(max_iter):
